// Fetches pinned Juicebox V6 deployment addresses from Bananapus/deploy-all-v6
// and emits slim TypeScript data files for the Hyvmind Funding tab.
// ABIs are deliberately NOT emitted — the app uses small typed ABIs
// (src/lib/juicebox/abis.ts) to keep the frontend bundle small. Run from the
// repo root:
//
//   node scripts/fetch-juicebox-deployments.mjs
//
// Output: src/frontend/src/data/juicebox/<chain>.ts  (default export per chain)
// The generated files are committed; this script is a dev-time regeneration tool.

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const REPO = "Bananapus/deploy-all-v6";
// Pinned commit observed as the `deploy-all-v6` submodule in Bananapus/version-6.
const REFS = ["316e9d4", "main"];

const CHAINS = [
  { dir: "base", chainId: 8453, out: "base.ts" },
  { dir: "base_sepolia", chainId: 84532, out: "baseSepolia.ts" },
];

// Core protocol contracts needed by the Funding tab.
const CONTRACTS = [
  "JBPermissions",
  "JBProjects",
  "JBDirectory",
  "JBSplits",
  "JBRulesets",
  "JBPrices",
  "JBTokens",
  "JBFundAccessLimits",
  "JBFeelessAddresses",
  "JBTerminalStore",
  "JBMultiTerminal",
  "JBController",
  "JBERC20",
];

const OUT_DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "src",
  "frontend",
  "src",
  "data",
  "juicebox",
);

async function fetchArtifact(chainDir, name, ref) {
  const url = `https://raw.githubusercontent.com/${REPO}/${ref}/deployments/${chainDir}/${name}.json`;
  const res = await fetch(url);
  if (!res.ok) return null;
  return res.json();
}

function emitTs(chain, contracts, refUsed) {
  const slim = {};
  for (const [name, art] of Object.entries(contracts)) {
    slim[name] = { address: art.address };
  }
  const json = JSON.stringify({ chainId: chain.chainId, contracts: slim }, null, 2);
  const header = `// Generated by scripts/fetch-juicebox-deployments.mjs — do not edit by hand.
// Source: ${REPO}@${refUsed} deployments/${chain.dir}
// Addresses only (no bytecode/abi) to keep the frontend bundle small.
import type { JuiceboxDeployment } from "./types";

const data: JuiceboxDeployment = ${json};

export default data;
`;
  writeFileSync(join(OUT_DIR, chain.out), header);
  console.log(`wrote ${chain.out} (${json.length} bytes)`);
}

async function main() {
  mkdirSync(OUT_DIR, { recursive: true });
  const refUsedByChain = {};
  for (const chain of CHAINS) {
    const contracts = {};
    let usedRef = null;
    for (const name of CONTRACTS) {
      let art = null;
      for (const ref of REFS) {
        art = await fetchArtifact(chain.dir, name, ref);
        if (art) {
          if (!usedRef) usedRef = ref;
          break;
        }
      }
      if (!art) {
        console.warn(`missing ${chain.dir}/${name}`);
        continue;
      }
      contracts[name] = art;
    }
    refUsedByChain[chain.dir] = usedRef ?? "none";
    emitTs(chain, contracts, usedRef ?? "none");
  }
  console.log("refs used:", refUsedByChain);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});